class stringx
{
  char* chars;
  void* my_buf;
public:
  stringx();
  stringx(const stringx&);
  stringx(const char*, int = -1);
  ~stringx();
  stringx& operator=(const stringx&);
};

class entity_id { unsigned int value; };

class filespec
{
public:
  stringx path;
  stringx name;
  stringx ext;
  filespec() {}
  explicit filespec(const stringx&);
  const filespec& operator=(const filespec& rhs)
  {
    path=rhs.path; name=rhs.name; ext=rhs.ext; return *this;
  }
};

class os_developer_options
{
public:
  enum flags_t { FLAG_STASH_ONLY };
  static os_developer_options* inst();
  bool is_flagged(flags_t) const;
};

class file_finder
{
public:
  stringx find_file(const stringx&, const stringx&);
};
extern file_finder* g_file_finder;

enum entity_flavor_t { ENTITY_PARTICLE_GENERATOR = 5 };
class particle_generator
{
public:
  particle_generator(const stringx&, const entity_id&, entity_flavor_t, unsigned int);
};

class world_dynamics_system
{
public:
  particle_generator* add_particle_generator(const stringx&, const entity_id&, unsigned int);
  void add_particle_generator(particle_generator*);
};

particle_generator*
world_dynamics_system::add_particle_generator( const stringx& fname,
                                               const entity_id& id,
                                               unsigned int flags )
{
  filespec spec(fname);
  if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_STASH_ONLY))
  {
    stringx actual_fname (g_file_finder->find_file( fname, ".ent" ));
    spec = filespec(actual_fname);
  }

  // all particle generators added to world must be nonstatic
  flags |= 0x08000000;
  particle_generator* ent = NEW particle_generator( spec.name, id, ENTITY_PARTICLE_GENERATOR, flags );

  add_particle_generator( ent );
  return ent;
}
